INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: hard / L4 — Section 302(b)(2) substantially disproportionate redemption
(3, 'C Corporations', 'Dawson owns 80 of the 200 outstanding shares of Pryor Corp (40% ownership). Pryor redeems 30 of Dawson''s shares for $150,000, reducing Dawson''s ownership to 50 of 170 shares (29.4%). Dawson''s basis in the 30 redeemed shares is $45,000. How should Dawson report the redemption?', '["$150,000 ordinary dividend income", "$150,000 return of capital", "$105,000 capital gain", "$45,000 capital gain"]'::jsonb, 2, 'Under Section 302(b)(2), a redemption is substantially disproportionate if post-redemption ownership is less than 80% of pre-redemption ownership. Here, 80% of 40% = 32%, and 29.4% < 32%, so exchange treatment applies under Section 302(a). Gain = $150,000 − $45,000 = $105,000 capital gain. Choice A is incorrect because the redemption meets the substantially disproportionate test and is not treated as a dividend distribution.', 'hard', 4),

-- Q2: easy / L1 — Form 1120 filing requirement
(3, 'C Corporations', 'What tax form does a C corporation use to file its annual federal income tax return?', '["Form 1065", "Form 1120", "Form 1120-S", "Schedule C"]'::jsonb, 1, 'Under IRS filing requirements, a C corporation files Form 1120, U.S. Corporation Income Tax Return. Form 1065 is for partnerships, Form 1120-S is for S corporations, and Schedule C is used by sole proprietors reporting business income on their individual returns. Choice A is incorrect because Form 1065 is the partnership information return, not the corporate income tax return.', 'easy', 1),

-- Q3: easy / L1 — Constructive dividend definition
(3, 'C Corporations', 'What is a constructive dividend in the context of C corporation taxation?', '["A payment or benefit to a shareholder reclassified as a dividend by the IRS", "A dividend formally declared by the board of directors", "A return of capital distribution that exceeds earnings and profits", "A dividend received by one corporation from another corporation"]'::jsonb, 0, 'Under IRC Section 316 and related case law, a constructive dividend is a benefit conferred on a shareholder—such as excessive compensation, personal expenses paid by the corporation, or below-market loans—that the IRS reclassifies as a taxable dividend. Choice B is incorrect because it describes a formal declared dividend; the key distinction is the absence of a formal declaration.', 'easy', 1),

-- Q4: medium / L3 — Organizational expenditures Section 248 phase-out
(3, 'C Corporations', 'Kestrel Corp is formed in 2026 and incurs $52,000 in organizational expenditures (legal fees for the corporate charter, state filing fees, and organizational meeting costs). Under Section 248, how much can Kestrel deduct in its first taxable year, and how is the remainder treated?', '["$52,000 deducted in full in the first year", "$5,000 deducted immediately; $47,000 amortized over 60 months", "$0 deducted immediately; $52,000 amortized over 180 months", "$3,000 deducted immediately; $49,000 amortized over 180 months"]'::jsonb, 3, 'Under Section 248, a corporation may deduct up to $5,000 of organizational expenditures immediately, but this amount is reduced dollar-for-dollar by expenditures exceeding $50,000. Since $52,000 exceeds $50,000 by $2,000, the immediate deduction is $5,000 − $2,000 = $3,000. The remaining $49,000 is amortized over 180 months. Choice B incorrectly applies the full $5,000 without the phase-out reduction and uses 60 months instead of 180.', 'medium', 3),

-- Q5: medium / L3 — Related party loss disallowance Section 267
(3, 'C Corporations', 'Hartwell owns 60% of Sterling Corp. Hartwell sells equipment with an adjusted basis of $80,000 to Sterling Corp for $55,000. Under Section 267, what is the tax consequence of this transaction to Hartwell?', '["Hartwell recognizes a $25,000 ordinary loss", "The $25,000 loss is disallowed", "Hartwell recognizes a $25,000 capital loss", "Sterling Corp reduces its basis to $55,000 and Hartwell claims a deferred loss"]'::jsonb, 1, 'Under Section 267(a)(1), losses from sales between related parties are disallowed. A shareholder owning more than 50% of a corporation is a related party under Section 267(b)(2). Hartwell''s 60% ownership triggers the rule, so the $25,000 loss ($55,000 − $80,000) is permanently disallowed to the seller. Choice D is incorrect because Section 267 permanently disallows the loss to the seller; while the buyer may benefit under Section 267(d) on a later resale, the seller never claims the loss.', 'medium', 3),

-- Q6: medium / L3 — DRD taxable income limitation exception when creating NOL
(3, 'C Corporations', 'Falcon Corp owns 30% of Eagle Corp and receives $200,000 in dividends. Falcon''s taxable income before the DRD is $120,000. The 65% DRD would be $130,000, which exceeds the taxable income limitation of $78,000. How does Section 246(b) resolve this limitation?', '["The DRD is permanently limited to $78,000", "The DRD is limited to $120,000, equal to taxable income", "The full $130,000 DRD is allowed because it creates a net operating loss", "The DRD is disallowed entirely because it exceeds taxable income"]'::jsonb, 2, 'Under Section 246(b), the DRD is generally limited to the applicable percentage of taxable income. However, an exception applies: if the full DRD would create or increase a net operating loss, the taxable income limitation does not apply. Here, the $130,000 DRD exceeds $120,000 taxable income, creating a $10,000 NOL, so the full DRD is allowed. Choice A incorrectly applies the limitation without recognizing the NOL exception.', 'medium', 3),

-- Q7: medium / L2 — Current E&P adjustments from taxable income
(3, 'C Corporations', 'Elm Corp has taxable income of $300,000 for 2026. In computing current E&P, Elm must add back $20,000 of tax-exempt municipal bond interest and subtract $63,000 of federal income tax paid. What is Elm Corp''s current E&P?', '["$257,000", "$320,000", "$237,000", "$357,000"]'::jsonb, 0, 'Under Section 312, current E&P begins with taxable income and requires adjustments. Tax-exempt income such as municipal bond interest is added because it represents economic income available for distribution. Federal income tax is subtracted because it reduces distributable cash. E&P = $300,000 + $20,000 − $63,000 = $257,000. Choice B incorrectly adds tax-exempt income without subtracting the federal tax liability.', 'medium', 2),

-- Q8: medium / L3 — Section 357(a) liability assumption reduces stock basis
(3, 'C Corporations', 'Weber transfers property with a basis of $120,000 and FMV of $300,000, subject to a $90,000 mortgage, to a newly formed corporation for 100% of the stock in a Section 351 exchange. The mortgage does not exceed the property''s basis. What is Weber''s basis in the stock received?', '["$120,000", "$300,000", "$210,000", "$30,000"]'::jsonb, 3, 'Under Sections 358(a) and 358(d), the shareholder''s stock basis equals the adjusted basis of property transferred ($120,000) decreased by the liability assumed ($90,000). Since the liability does not exceed basis, no gain is recognized under Section 357(c), and stock basis is $120,000 − $90,000 = $30,000. Choice A is incorrect because it ignores the liability reduction; Section 358(d) treats the assumption as money received for basis computation purposes.', 'medium', 3),

-- Q9: medium / L3 — Corporation's basis in contributed property Section 362(a) with recognized gain
(3, 'C Corporations', 'Nash transfers equipment with a basis of $70,000 and FMV of $150,000 to a newly formed corporation for 100% of the stock and $20,000 cash in a Section 351 exchange. Nash recognizes $20,000 of gain. Under Section 362, what is the corporation''s basis in the equipment?', '["$70,000", "$90,000", "$150,000", "$80,000"]'::jsonb, 1, 'Under Section 362(a), the corporation''s basis in property received in a Section 351 exchange equals the transferor''s adjusted basis ($70,000) plus any gain recognized by the transferor ($20,000). The corporation''s basis is $70,000 + $20,000 = $90,000. Choice A incorrectly uses only the transferor''s basis without adding the recognized gain; Section 362(a) adjusts upward to prevent permanent double taxation.', 'medium', 3),

-- Q10: hard / L4 — Debt vs equity reclassification Section 385
(3, 'C Corporations', 'Crestwood Corp issues a $2,000,000 instrument to its sole shareholder labeled as a loan, bearing 2% interest with no fixed maturity date and repayment subordinated to all creditors. The debt-to-equity ratio is 9:1. The IRS reclassifies the instrument as equity. Evaluate the primary tax consequence of this reclassification.', '["Interest payments become nondeductible dividends, increasing Crestwood''s taxable income", "Interest payments remain deductible but are reported as dividends to the shareholder", "Principal repayments become taxable capital gains to the shareholder", "The instrument is treated as a capital contribution with no immediate tax effect"]'::jsonb, 0, 'Under Section 385 and related case law, when the IRS reclassifies purported debt as equity, interest payments lose deductibility to the corporation and are recharacterized as dividend distributions. This increases taxable income because the corporation loses the interest deduction. Choice B is incorrect because the deduction and the shareholder''s characterization must both change—a payment cannot be simultaneously deductible interest and a nondeductible dividend.', 'hard', 4),

-- Q11: easy / L1 — Qualified dividend rates for individual shareholders
(3, 'C Corporations', 'At what tax rates are qualified dividends from a C corporation taxed to individual shareholders?', '["Ordinary income rates of 10% to 37%", "A flat rate of 21%", "Preferential rates of 0%, 15%, or 20%", "A flat rate of 15%"]'::jsonb, 2, 'Under Section 1(h)(11), qualified dividends received by individual shareholders are taxed at the same preferential rates as long-term capital gains—0%, 15%, or 20% depending on the taxpayer''s income bracket. This treatment was enacted to reduce the burden of double taxation on corporate earnings. Choice A incorrectly applies ordinary income rates; the qualified dividend provision specifically overrides ordinary rate treatment.', 'easy', 1),

-- Q12: medium / L2 — Corporate estimated tax safe harbor for non-large corporation
(3, 'C Corporations', 'Vega Corp, a calendar-year C corporation, expects a current-year tax of $168,000. Its prior-year tax liability was $150,000. Vega is not a large corporation. What is the minimum estimated tax Vega must pay to avoid the underpayment penalty under Section 6655?', '["$168,000", "$126,000", "$134,400", "$150,000"]'::jsonb, 3, 'Under Section 6655, a corporation (other than a large corporation) avoids the underpayment penalty by paying the lesser of 100% of current-year tax ($168,000) or 100% of prior-year tax ($150,000). The prior-year safe harbor of $150,000 is the minimum required. Choice C incorrectly applies an 80% threshold, which is the NOL deduction limitation under Section 172, not the estimated tax safe harbor.', 'medium', 2),

-- Q13: medium / L2 — Shareholder's holding period tacking Section 1223(1)
(3, 'C Corporations', 'Palmer transfers a capital asset held for three years with a basis of $40,000 and FMV of $100,000 to a newly formed corporation for 100% of the stock under Section 351. When does Palmer''s holding period for the stock begin?', '["The holding period includes the time Palmer held the transferred property", "The holding period begins on the date of the Section 351 exchange", "The holding period begins on the date the corporation is incorporated", "The holding period begins six months after the exchange"]'::jsonb, 0, 'Under Section 1223(1), when property has a transferred basis (as in a Section 351 exchange), the shareholder''s holding period for the stock includes the period the transferred property was held. Palmer tacks the three-year holding period of the capital asset onto the stock. Choice B is incorrect because Section 1223(1) permits tacking whenever the stock basis is determined by reference to the transferred property''s basis.', 'medium', 2),

-- Q14: easy / L2 — Accumulated E&P as dividend source when current E&P is zero
(3, 'C Corporations', 'Birch Corp has current-year E&P of $0 and accumulated E&P of $75,000. Birch distributes $50,000 to its sole shareholder. How is the distribution characterized?', '["Return of capital reducing shareholder''s stock basis", "Taxable dividend of $50,000", "Nontaxable because current E&P is zero", "Capital gain of $50,000"]'::jsonb, 1, 'Under Section 316(a), distributions are dividends to the extent of current E&P plus accumulated E&P. Even though current E&P is zero, the $50,000 is fully covered by accumulated E&P of $75,000 and is treated as a taxable dividend. Choice C incorrectly assumes only current E&P determines dividend treatment; Section 316(a)(2) specifically provides that accumulated E&P is a separate source.', 'easy', 2),

-- Q15: medium / L2 — Schedule M-1 book-tax reconciliation
(3, 'C Corporations', 'Drake Corp reports $500,000 of net income per books. Drake''s books include $30,000 of federal income tax expense, $15,000 of meals expense (50% nondeductible), and $10,000 of tax-exempt municipal bond interest. What is Drake''s taxable income per the Schedule M-1 reconciliation?', '["$537,500", "$545,000", "$527,500", "$522,500"]'::jsonb, 2, 'Schedule M-1 reconciles book income to taxable income. Federal income tax ($30,000) is added back because it is nondeductible under Section 275. The nondeductible portion of meals ($7,500) is added back under Section 274. Tax-exempt bond interest ($10,000) is subtracted. Taxable income = $500,000 + $30,000 + $7,500 − $10,000 = $527,500. Choice A incorrectly adds back the full $15,000 meals expense rather than only the 50% nondeductible portion.', 'medium', 2),

-- Q16: medium / L3 — Section 162(m) $1M compensation deduction cap
(3, 'C Corporations', 'Ridgeline Corp, a publicly traded C corporation, pays its CEO $2,500,000 in total compensation for 2026. The CEO is a covered employee under Section 162(m). How much of the CEO''s compensation can Ridgeline deduct?', '["$1,000,000", "$2,500,000", "$1,500,000", "$500,000"]'::jsonb, 0, 'Under Section 162(m), a publicly traded corporation may not deduct compensation exceeding $1,000,000 paid to a covered employee. The TCJA eliminated the performance-based compensation exception, so all forms of compensation count toward the $1,000,000 cap. The excess $1,500,000 is permanently nondeductible. Choice B is incorrect because it ignores the Section 162(m) limitation entirely and treats the full amount as deductible.', 'medium', 3),

-- Q17: medium / L2 — Consent dividends to avoid PHC tax Section 565
(3, 'C Corporations', 'Redstone Corp is a personal holding company with undistributed PHC income of $400,000. The shareholders agree to report $400,000 as consent dividends on Schedule PH. How does this election affect Redstone''s PHC tax liability?', '["The PHC tax is deferred until actual distributions are made", "The PHC tax is reduced by 50% of the consent dividend amount", "Consent dividends have no effect on the PHC tax", "The PHC tax is eliminated because consent dividends reduce undistributed PHC income to zero"]'::jsonb, 3, 'Under Section 565, consent dividends are treated as if actually distributed and immediately contributed back as paid-in capital. They reduce undistributed PHC income dollar-for-dollar. Since the $400,000 consent dividend equals undistributed PHC income, the tax base is reduced to zero, eliminating the PHC tax. Choice A is incorrect because consent dividends provide immediate relief, not deferral; the mechanism specifically avoids requiring actual cash distributions.', 'medium', 2),

-- Q18: hard / L4 — Affiliated group Section 1504 consolidated return eligibility
(3, 'C Corporations', 'Atlas Corp owns 85% of the voting stock and 75% of the total value of Bridge Corp. Atlas also owns 80% of the voting stock and 80% of the total value of Canyon Corp. Atlas wants to file a consolidated return. Evaluate which subsidiaries may be included in the affiliated group under Section 1504.', '["Both Bridge Corp and Canyon Corp qualify", "Only Canyon Corp qualifies because Bridge Corp fails the 80% value test", "Neither subsidiary qualifies because Atlas must own 100% to consolidate", "Only Bridge Corp qualifies because it has the higher voting ownership"]'::jsonb, 1, 'Under Section 1504(a), an affiliated group requires the parent to own at least 80% of total voting power AND at least 80% of total value of each subsidiary''s stock. Atlas owns 85% vote but only 75% value of Bridge Corp, failing the value test. Atlas owns 80% vote and 80% value of Canyon Corp, meeting both thresholds. Choice A is incorrect because Bridge Corp''s 75% value falls below the 80% threshold; both prongs must be satisfied simultaneously.', 'hard', 4),

-- Q19: easy / L1 — C corporation Form 1120 due date
(3, 'C Corporations', 'What is the filing due date for a calendar-year C corporation''s Form 1120?', '["March 15 of the following year", "June 15 of the following year", "April 15 of the following year", "September 15 of the following year"]'::jsonb, 2, 'Under Section 6072(b), a C corporation must file its income tax return by the 15th day of the 4th month after the close of its tax year. For a calendar-year corporation, this is April 15. Choice A is incorrect because March 15 is the filing deadline for S corporations and partnerships under Section 6072(b) as amended, not C corporations.', 'easy', 1),

-- Q20: hard / L4 — Section 267 constructive ownership family attribution
(3, 'C Corporations', 'Logan owns 30% of Apex Corp directly, and Logan''s daughter owns 25% of Apex Corp. Logan sells equipment with an adjusted basis of $90,000 to Apex Corp for $65,000. Logan argues he is not a related party because his direct ownership is only 30%. Evaluate whether Logan''s $25,000 loss is deductible.', '["The loss is disallowed because Logan constructively owns 55% through family attribution", "The loss is deductible because Logan''s direct ownership is only 30%", "The loss is deductible because parent-child attribution does not apply to corporations", "The loss is deferred until Apex sells the equipment to an unrelated party"]'::jsonb, 0, 'Under Section 267(c)(4), stock owned by family members (including children) is attributed to the taxpayer. Logan constructively owns 30% (direct) + 25% (daughter) = 55%, exceeding the more-than-50% threshold in Section 267(b)(2). The $25,000 loss is disallowed under Section 267(a)(1). Choice B incorrectly ignores constructive ownership; Section 267(c) family attribution rules must be applied before testing the related party threshold.', 'hard', 4),

-- Q21: medium / L3 — Startup expenditures Section 195
(3, 'C Corporations', 'Pinecrest Corp begins operations on January 1, 2026, having incurred $48,000 in startup expenditures (market research and employee training) before opening. Pinecrest uses the calendar year. Under Section 195, what is the maximum amount Pinecrest may deduct in its first tax year?', '["$48,000 deducted in full", "$2,867 (amortization only, no immediate deduction)", "$8,000 ($5,000 immediate plus $3,000 amortization)", "$7,867 ($5,000 immediate plus $2,867 amortization)"]'::jsonb, 3, 'Under Section 195, a corporation may deduct up to $5,000 of startup expenditures immediately (no phase-out since $48,000 is below $50,000). The remaining $43,000 is amortized over 180 months. For a full 12-month year, amortization is $43,000 / 180 x 12 = $2,867. Total first-year deduction is $5,000 + $2,867 = $7,867. Choice C incorrectly computes $3,000 amortization, which does not reflect the 180-month period applied to a $43,000 balance.', 'medium', 3),

-- Q22: medium / L2 — Dividends paid deduction reduces AET exposure
(3, 'C Corporations', 'Summit Corp has accumulated taxable income of $600,000 before considering dividends paid. During the year, Summit distributes $250,000 in cash dividends to its shareholders. How do the dividends affect Summit''s accumulated earnings tax computation?', '["Dividends have no effect on the accumulated earnings tax calculation", "The $250,000 dividends paid reduces accumulated taxable income to $350,000", "Only 50% of dividends paid reduces accumulated taxable income", "Dividends paid increase accumulated taxable income by $250,000"]'::jsonb, 1, 'Under Section 535(a), accumulated taxable income is reduced by the dividends paid deduction under Section 561. The full $250,000 of dividends paid during the year reduces accumulated taxable income to $350,000, lowering AET exposure. Choice A is incorrect because the dividends paid deduction is the primary mechanism for reducing AET liability; Congress designed the AET to encourage corporations to distribute earnings.', 'medium', 2),

-- Q23: easy / L1 — Corporate capital gains no preferential rate
(3, 'C Corporations', 'How are net long-term capital gains taxed for a C corporation?', '["At the same flat 21% rate as ordinary income", "At a preferential rate of 15%", "At a preferential rate of 20%", "Capital gains are exempt from corporate tax"]'::jsonb, 0, 'Under IRC Section 11, C corporation capital gains are taxed at the flat 21% corporate rate with no preferential rate. Unlike individuals who benefit from reduced capital gains rates under Section 1(h), corporations pay the same rate on all types of income. Choice B incorrectly applies individual preferential capital gains rates to a corporate taxpayer.', 'easy', 1),

-- Q24: medium / L2 — Corporation's holding period tacking Section 1223(2)
(3, 'C Corporations', 'Torres contributes a machine held for four years (basis $60,000, FMV $120,000) to a newly formed corporation for 100% of the stock under Section 351. Six months after the exchange, the corporation sells the machine. What is the corporation''s holding period for the machine?', '["Six months, beginning on the date of the Section 351 exchange", "One year, the minimum required for long-term treatment", "Four years and six months, tacking Torres''s holding period", "Four years, ending on the date of the Section 351 exchange"]'::jsonb, 2, 'Under Section 1223(2), when a corporation acquires property with a transferred basis under Section 362, it tacks the transferor''s holding period. The corporation includes Torres''s four-year holding period plus its own six months, totaling four years and six months for capital gain characterization. Choice A is incorrect because it ignores the tacking rule; Section 1223(2) applies whenever the corporation''s basis is determined by reference to the transferor''s basis.', 'medium', 2),

-- Q25: medium / L2 — Golden parachute payments Section 280G nondeductible
(3, 'C Corporations', 'Cascade Corp is acquired in a change-of-control transaction. Its CEO receives a $3,000,000 parachute payment that exceeds three times the CEO''s $500,000 base amount. Under Section 280G, how is the excess parachute payment treated for Cascade Corp?', '["Fully deductible as reasonable compensation", "Deductible up to the $1,500,000 threshold", "Subject to a 20% excise tax on the corporation", "The $2,500,000 excess parachute payment is nondeductible"]'::jsonb, 3, 'Under Section 280G, excess parachute payments are nondeductible by the payor corporation. The excess equals the total payment ($3,000,000) minus the base amount ($500,000) = $2,500,000. This amount is permanently nondeductible to Cascade. Choice C incorrectly assigns the excise tax to the corporation; under Section 4999, the 20% excise tax is imposed on the recipient executive, not the payor corporation.', 'medium', 2),

-- Q26: hard / L4 — Section 163(j) interest deduction limitation
(3, 'C Corporations', 'Keystone Corp has adjusted taxable income of $2,000,000, business interest expense of $800,000, and business interest income of $50,000 for 2026. Keystone has no floor plan financing. Under Section 163(j), evaluate how much business interest Keystone may deduct and the treatment of any disallowed amount.', '["$650,000 deductible; $150,000 permanently disallowed", "$650,000 deductible; $150,000 carried forward indefinitely", "$600,000 deductible; $200,000 carried forward for five years", "$800,000 fully deductible because ATI exceeds the interest expense"]'::jsonb, 1, 'Under Section 163(j), the business interest deduction is limited to business interest income ($50,000) plus 30% of ATI ($600,000), totaling $650,000. The remaining $150,000 is carried forward indefinitely under Section 163(j)(2). Choice A incorrectly states the disallowed amount is permanent; the TCJA provides for indefinite carryforward of disallowed business interest expense to future tax years.', 'hard', 4),

-- Q27: easy / L1 — C corporation fiscal year flexibility
(3, 'C Corporations', 'Which type of tax year may a C corporation generally elect?', '["Only a calendar year ending December 31", "Only a 52-53 week tax year", "Either a calendar year or any fiscal year", "Only a fiscal year ending June 30 or September 30"]'::jsonb, 2, 'Under Section 441, a C corporation may adopt either a calendar year or any fiscal year ending on the last day of any month. Unlike S corporations, which generally must use a calendar year under Section 1378, C corporations have unrestricted flexibility in choosing their tax year. Choice A incorrectly limits C corporations to the calendar year; that restriction applies to S corporations and personal service corporations.', 'easy', 1),

-- Q28: easy / L1 — Cash method eligibility Section 448(c) gross receipts test
(3, 'C Corporations', 'Under the TCJA, what determines whether a C corporation may use the cash method of accounting?', '["Average annual gross receipts must not exceed the Section 448(c) threshold", "The corporation must have fewer than 100 shareholders", "Only S corporations may elect the cash method", "All C corporations are required to use the accrual method"]'::jsonb, 0, 'Under Section 448(c) as amended by the TCJA, a C corporation may use the cash method of accounting if its average annual gross receipts for the three prior tax years do not exceed the inflation-adjusted threshold (approximately $30 million for 2026). Choice D is incorrect because the TCJA expanded cash-method eligibility to qualifying C corporations that meet the gross receipts test.', 'easy', 1),

-- Q29: easy / L1 — Reasonable compensation standard Section 162(a)(1)
(3, 'C Corporations', 'What standard does the IRS apply to evaluate whether compensation paid to a shareholder-employee of a C corporation is deductible?', '["The compensation must not exceed $1,000,000", "The compensation must be approved by a majority of shareholders", "The compensation must be less than 50% of corporate revenue", "The compensation must be reasonable for the services actually rendered"]'::jsonb, 3, 'Under Section 162(a)(1), a corporation may deduct a reasonable allowance for salaries and compensation for personal services actually rendered. The IRS evaluates factors including qualifications, duties, comparable salaries, and corporate earnings. Choice A is incorrect because it confuses this standard with the Section 162(m) limitation, which applies only to covered employees of publicly traded corporations.', 'easy', 1),

-- Q30: hard / L3 — Family attribution prevents complete termination Section 302
(3, 'C Corporations', 'Monroe owns 40% of Granite Corp. Granite redeems all of Monroe''s shares for $500,000, but Monroe''s spouse continues to own 30% of Granite. Monroe does not file a waiver of family attribution under Section 302(c)(2). Under Section 302(b), how is the redemption treated?', '["Exchange treatment under Section 302(b)(3) as a complete termination", "Dividend treatment because family attribution prevents complete termination", "Exchange treatment under Section 302(b)(1) as not essentially equivalent to a dividend", "Exchange treatment under Section 302(b)(2) as substantially disproportionate"]'::jsonb, 1, 'Under Section 302(b)(3), a redemption qualifies as a complete termination only if the shareholder''s entire interest is eliminated. Section 318(a)(1) attributes a spouse''s stock to the shareholder. Without a waiver under Section 302(c)(2), Monroe constructively owns the spouse''s 30%, so the interest is not completely terminated and the redemption is treated as a Section 301 dividend distribution. Choice A is incorrect because family attribution must be applied unless affirmatively waived.', 'hard', 3)
;

COMMIT;
